use super::*;
use super::directories::*;
fn lab()->PathBuf{let base=Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().join("tests/work/m4");fs::create_dir_all(&base).unwrap();let p=base.join(uuid());super::directories::create_private_dir(&p).unwrap();p}
fn manager(base:&Path)->DataManager{DataManager::open(&base.join("locator"),&base.join("data"),16384).unwrap()}
fn seeded(m:&mut DataManager)->(String,String,String){let s=m.store_mut();let(doc,rev)=s.create_document("physical-key",&"a".repeat(64),30,"合成测试.pdf").unwrap();let c=s.conversation(&doc).unwrap();s.message(&c,&rev,None,"合成历史：不能丢失",false,&model::MessageMetadata{provider:Some("synthetic".into()),model:None,preset_version:None,request_id:None,sent_context_hash:None,slot:None}).unwrap();s.position(&doc,&rev,15,125.,210.).unwrap();s.update_settings(true,16384).unwrap();let recovery=s.recovery_put(b"synthetic unsaved draft").unwrap();(doc,c,recovery)}
#[test]#[ignore="explicit new LocalAppData synthetic namespace; parent invokes this entry"]
fn default_data_reopen_child(){let base=PathBuf::from(std::env::var_os("M4_DEFAULT_VALIDATION").expect("private parent"));let expected=PathBuf::from(std::env::var_os("LOCALAPPDATA").unwrap()).join("io.github.ainativepdfreader-m4-validation");assert_eq!(base.parent(),Some(expected.as_path()));uuid::Uuid::parse_str(base.file_name().unwrap().to_str().unwrap()).unwrap();let m=manager(&base);let conv=std::env::var("M4_SYNTHETIC_CONVERSATION").unwrap();let draft=std::env::var("M4_SYNTHETIC_RECOVERY").unwrap();let doc=std::env::var("M4_SYNTHETIC_DOCUMENT").unwrap();assert_eq!(m.store().messages(&conv).unwrap().len(),1);assert_eq!(m.store().recovery_get(&draft).unwrap(),b"synthetic unsaved draft");assert!(m.store().settings().unwrap().unwrap().thumbnail_open);let(rev,_)=m.store().current_revision(&doc).unwrap();assert_eq!(m.store().local_drafts(&doc,&rev).unwrap().len(),1);assert_eq!(m.list_backups().unwrap().len(),1);m.store().check().unwrap();assert!(m.info().private_acl);}
#[test]#[ignore="explicit C LocalAppData synthetic persistence test; M4_DEFAULT_VALIDATION_RUN=1"]
fn default_localappdata_persistence_across_actual_process_restart(){assert_eq!(std::env::var("M4_DEFAULT_VALIDATION_RUN").ok().as_deref(),Some("1"));let base=PathBuf::from(std::env::var_os("LOCALAPPDATA").unwrap()).join("io.github.ainativepdfreader-m4-validation").join(uuid());super::directories::prepare_default_validation(&base).unwrap();let mut m=manager(&base);let(doc,conv,recovery)=seeded(&mut m);let(rev,_)=m.store().current_revision(&doc).unwrap();m.store_mut().put_local_draft(&doc,&rev,&uuid(),r#"{"schema":1,"pdfjs":"6.4.299","entries":[]}"#).unwrap();m.backup().unwrap();let root=m.info().path;drop(m);let output=std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","storage::directories_tests::default_data_reopen_child","--ignored","--nocapture"]).env("M4_DEFAULT_VALIDATION",&base).env("M4_SYNTHETIC_CONVERSATION",conv).env("M4_SYNTHETIC_RECOVERY",recovery).env("M4_SYNTHETIC_DOCUMENT",doc).output().unwrap();assert!(output.status.success(),"{} {}",String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));println!("new default-parent synthetic namespace persisted DB/settings/draft/backup through actual process restart: {root}");}
#[test]
fn private_acl_and_root_authority_are_actual(){let base=lab();let m=manager(&base);assert!(m.info().private_acl);let p=PathBuf::from(m.info().path);let root=super::directories::open_owned_root(&p);assert!(root.is_err(),"exclusive root manager lock");let db=leaf_guard(&p.join("history.sqlite"),false).unwrap();super::directories::check_private_file(&db,false).unwrap();let alias=base.join("aliased.sqlite");assert!(DataManager::open(&base.join("locator"),&base.join("other"),16384).is_err());drop(db);drop(m);fs::hard_link(p.join("history.sqlite"),&alias).unwrap();assert!(leaf_guard(&alias,false).is_err());assert!(leaf_guard(&p.join("history.sqlite"),false).is_err());println!("actual current-user/SYSTEM/admin protected ACL checked; existing hardlinked leaves and competing manager refused");}
#[test]
fn complete_migration_and_restore_preserve_materials(){let base=lab();let mut m=manager(&base);let(_,conv,recovery)=seeded(&mut m);let expected=m.store().messages(&conv).unwrap();let backup=m.backup().unwrap();assert_eq!(m.list_backups().unwrap().len(),1);let old=PathBuf::from(m.info().path);let parent=base.join("selected-d");fs::create_dir(&parent).unwrap();let info=m.migrate_to(&parent,"").unwrap();assert!(info.generation>1);assert!(old.join("history.sqlite").exists());assert_eq!(m.store().messages(&conv).unwrap(),expected);assert_eq!(m.store().recovery_get(&recovery).unwrap(),b"synthetic unsaved draft");assert!(m.store().settings().unwrap().unwrap().thumbnail_open);assert_eq!(m.list_backups().unwrap()[0].id,backup.id);let selected=PathBuf::from(info.path);drop(m);let mut m=manager(&base);assert_eq!(PathBuf::from(m.info().path),selected);let restored=m.restore_backup(&backup.id).unwrap();assert_ne!(PathBuf::from(restored.path),selected);assert_eq!(m.store().messages(&conv).unwrap(),expected);assert_eq!(m.store().recovery_get(&recovery).unwrap(),b"synthetic unsaved draft");assert!(selected.join("history.sqlite").exists());println!("Online Backup + settings + drafts + important backups migrated; locator reopen + restore into new root passed");}
#[test]
fn pdf_archive_survives_data_move_cache_clear_and_history_restore(){
    let base=lab();let mut m=manager(&base);let(doc,conv,_)=seeded(&mut m);let backup=m.backup().unwrap();
    let(_files,outcome,_)=crate::original_commit::real_commit_with_before(|_,_|());
    crate::original_commit::acknowledge(&outcome).unwrap();m.archive_pdf(&outcome,&doc).unwrap();
    let relative=PathBuf::from("pdf-backups").join(&doc).join(format!(".ainative-backup-{}",outcome.receipt.event_id())).join("verified-old.pdf");
    let before=fs::read(Path::new(&m.info().path).join(&relative)).unwrap();
    assert_eq!(crate::save_core::hash(&before),outcome.receipt.old_hash());assert!(!outcome.materials.exists());
    let parent=base.join("move");fs::create_dir(&parent).unwrap();let moved=m.migrate_to(&parent,"").unwrap();
    assert_eq!(fs::read(Path::new(&moved.path).join(&relative)).unwrap(),before);
    m.store_mut().clear_rebuildable_cache().unwrap();drop(m);let mut m=manager(&base);
    assert_eq!(m.info().path,moved.path);let restored=m.restore_backup(&backup.id).unwrap();
    assert_eq!(fs::read(Path::new(&restored.path).join(&relative)).unwrap(),before);
    assert_eq!(m.store().messages(&conv).unwrap().len(),1);drop(m);
    assert_eq!(manager(&base).info().path,restored.path);
}
#[test]
fn migration_failures_keep_original_and_never_publish_bad_target(){let base=lab();let mut m=manager(&base);let(_,conv,_)=seeded(&mut m);let old=m.info().path;let parent=base.join("target");fs::create_dir(&parent).unwrap();for fault in ["no-space","after-snapshot","before-switch","corrupt-target"]{assert!(m.migrate_to(&parent,fault).is_err(),"{fault}");assert_eq!(m.info().path,old);assert_eq!(m.store().messages(&conv).unwrap().len(),1);m.store().check().unwrap();}drop(m);let m=manager(&base);assert_eq!(m.info().path,old);assert_eq!(m.store().messages(&conv).unwrap().len(),1);println!("bounded no-space/after-snapshot/before-switch/corrupt-target failures retained original; incomplete targets preserved");}
#[test]
fn committed_target_corruption_rolls_back_with_notice(){let base=lab();let mut m=manager(&base);let(_,conv,_)=seeded(&mut m);let old=m.info().path;let parent=base.join("target");fs::create_dir(&parent).unwrap();let next=m.migrate_to(&parent,"").unwrap();drop(m);fs::write(Path::new(&next.path).join("history.sqlite"),b"corrupt disposable target").unwrap();let m=manager(&base);assert_eq!(m.info().path,old);assert!(m.info().warning.is_some());assert_eq!(m.store().messages(&conv).unwrap().len(),1);assert!(Path::new(&next.path).join("history.sqlite").exists());println!("corrupt activated destination -> explicit retained-source rollback, no delete");}
#[test]
fn missing_committed_database_never_initializes_empty(){let base=lab();let mut m=manager(&base);let(_,conv,_)=seeded(&mut m);let old=m.info().path;let parent=base.join("target");fs::create_dir(&parent).unwrap();let next=m.migrate_to(&parent,"").unwrap();drop(m);let db=Path::new(&next.path).join("history.sqlite");fs::rename(&db,db.with_extension("synthetic-missing")).unwrap();let m=manager(&base);assert_eq!(m.info().path,old);assert!(m.info().warning.is_some());assert_eq!(m.store().messages(&conv).unwrap().len(),1);assert!(!db.exists());println!("missing committed DB: refused empty reinitialization and retained-source history restored");}
#[test]
fn denied_target_acl_and_occupied_old_root_preserve_history(){let base=lab();let mut m=manager(&base);let(_,conv,_)=seeded(&mut m);let old=m.info().path;let target=base.join("denied-target");fs::create_dir(&target).unwrap();super::directories::deny_test_directory_writes(&target).unwrap();let error=m.migrate_to(&target,"").err().unwrap();match error{DataError::Io(e)=>assert_eq!(e.raw_os_error(),Some(5)),other=>panic!("expected real ACCESS_DENIED, got {other:?}")};assert_eq!(m.info().path,old);assert_eq!(m.store().messages(&conv).unwrap().len(),1);assert!(fs::rename(Path::new(&old),base.join("stolen-old-root")).is_err());let allowed=base.join("allowed-target");fs::create_dir(&allowed).unwrap();m.migrate_to(&allowed,"").unwrap();assert!(Path::new(&old).join("history.sqlite").exists());assert_eq!(m.store().messages(&conv).unwrap().len(),1);println!("real ERROR_ACCESS_DENIED(5) target; occupied old root remains accessible and migration keeps old material");}
#[test]
fn missing_live_draft_rolls_back_without_empty_recovery(){let base=lab();let mut m=manager(&base);let(doc,_,_)=seeded(&mut m);let(rev,_)=m.store().current_revision(&doc).unwrap();let draft=uuid();m.store_mut().put_local_draft(&doc,&rev,&draft,r#"{"schema":1,"pdfjs":"6.4.299","entries":[]}"#).unwrap();let old=m.info().path;let target=base.join("target");fs::create_dir(&target).unwrap();let next=m.migrate_to(&target,"").unwrap();drop(m);let recovery=Path::new(&next.path).join("recovery");let source=fs::read_dir(&recovery).unwrap().find_map(|e|{let e=e.unwrap();let bytes=fs::read(e.path()).unwrap();if bytes.starts_with(b"{"){Some(e.path())}else{None}}).unwrap();fs::rename(&source,source.with_extension("missing-synthetic")).unwrap();let m=manager(&base);assert_eq!(m.info().path,old);assert!(m.info().warning.is_some());assert_eq!(m.store().local_drafts(&doc,&rev).unwrap().len(),1);assert!(!source.exists());println!("missing live draft rejected; retained original draft recovered without silent empty recovery creation");}
#[test]
fn danger_inputs_and_cache_cleanup_cannot_touch_persistent_data(){let base=lab();let mut m=manager(&base);let(doc,conv,recovery)=seeded(&mut m);let(rev,_)=m.store().current_revision(&doc).unwrap();m.store_mut().put_local_draft(&doc,&rev,&uuid(),r#"{"schema":1,"pdfjs":"6.4.299","entries":[]}"#).unwrap();let backup=m.backup().unwrap();let cache=m.store().cache_put(b"rebuildable").unwrap();m.store_mut().clear_rebuildable_cache().unwrap();assert!(m.store().cache_get(&cache).is_err());assert_eq!(m.store().messages(&conv).unwrap().len(),1);assert_eq!(m.store().local_drafts(&doc,&rev).unwrap().len(),1);assert!(m.store().recovery_get(&recovery).is_ok());assert_eq!(m.list_backups().unwrap()[0].id,backup.id);let old=m.info().path;
    for input in [r"relative\folder",r"\\untrusted-server\share",r"\\?\GLOBALROOT\Device\HarddiskVolume1",r"D:\not-a-real-folder:ads",r"D:\"]{assert!(m.migrate_to(Path::new(input),"").is_err());assert_eq!(m.info().path,old);}
    let public=base.join("public-delete-child");fs::create_dir(&public).unwrap();super::directories::grant_test_parent_delete_child(&public).unwrap();assert!(m.migrate_to(&public,"").is_err());assert_eq!(m.info().path,old);println!("dangerous path / actual ordinary-user DELETE_CHILD ACL rejected; clear cache retains history/drafts/backups");}
#[test]
fn unfinished_backup_keeps_prior_verified_backup_available(){let base=lab();let mut m=manager(&base);let(_,conv,_)=seeded(&mut m);let backup=m.backup().unwrap();let pending=m.store().root.path.join("backups").join(uuid());let held=super::directories::create_private_dir(&pending).unwrap();fs::write(pending.join("history.sqlite"),b"unfinished synthetic snapshot").unwrap();drop(held);assert_eq!(m.list_backups().unwrap().len(),1);assert_eq!(m.list_backups().unwrap()[0].id,backup.id);assert_eq!(m.info().incomplete_backups,1);assert!(m.info().warning.is_some());m.restore_backup(&backup.id).unwrap();assert_eq!(m.store().messages(&conv).unwrap().len(),1);assert!(pending.join("history.sqlite").exists());println!("unfinished backup materials retained; prior verified backup still listed and restored safely");}
