fn directory_exit_actor(){let Some(base)=std::env::var_os("M4_DIRECTORY_EXIT_BASE")else{return;};let fault=std::env::var("M4_DIRECTORY_EXIT_FAULT").unwrap();let base=PathBuf::from(base);let mut m=manager(&base);m.migrate_to(&base.join("target"),&fault).unwrap();panic!("child failed to exit");}
#[test]
fn process_interruption_before_and_after_activation(){for fault in ["exit-after-snapshot","exit-before-switch","exit-after-switch"]{let base=lab();let mut m=manager(&base);let(_,conv,_)=seeded(&mut m);let old=m.info().path;fs::create_dir(base.join("target")).unwrap();drop(m);let output=std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","storage::directories_tests::directory_exit_actor","--nocapture"]).env("M4_DIRECTORY_EXIT_BASE",&base).env("M4_DIRECTORY_EXIT_FAULT",fault).output().unwrap();assert_eq!(output.status.code(),Some(74));let m=manager(&base);if fault=="exit-after-switch"{assert_ne!(m.info().path,old);}else{assert_eq!(m.info().path,old);}assert_eq!(m.store().messages(&conv).unwrap().len(),1);m.store().check().unwrap();assert!(Path::new(&old).join("history.sqlite").exists());}println!("actual child exit 74 after snapshot / before activation / after activation: committed history consistent");}
#[test]
#[ignore="explicit synthetic C/D test: set M4_CROSS_DRIVE=1 and run --ignored"]
fn cross_drive_roundtrip(){
    assert_eq!(std::env::var("M4_CROSS_DRIVE").ok().as_deref(),Some("1"));
    let base=lab();let mut m=manager(&base);let(doc,conv,recovery)=seeded(&mut m);let(revision,_)=m.store().current_revision(&doc).unwrap();
    let draft=uuid();m.store_mut().put_local_draft(&doc,&revision,&draft,r#"{"schema":1,"pdfjs":"6.4.299","entries":[]}"#).unwrap();let backup=m.backup().unwrap();
    // In the managed environment LOCALAPPDATA is redirected to a capability-
    // writable sandbox. Do not weaken the production parent ACL rule. This
    // explicit experiment creates only new, private synthetic materials below
    // the already safe user-profile ancestor; it changes no default locator.
    let c_parent=PathBuf::from(std::env::var_os("USERPROFILE").expect("Windows user profile")).join(".ai-native-pdf-reader-m4-synthetic-tests").join(uuid());
    super::directories::prepare_synthetic_cross_parent(&c_parent).unwrap();
    let c=m.migrate_to(&c_parent,"").unwrap();assert!(c.path.to_ascii_lowercase().contains("c:\\"));
    assert_eq!(m.store().messages(&conv).unwrap().len(),1);assert_eq!(m.store().recovery_get(&recovery).unwrap(),b"synthetic unsaved draft");assert_eq!(m.store().local_drafts(&doc,&revision).unwrap().len(),1);assert_eq!(m.list_backups().unwrap()[0].id,backup.id);
    let d=m.migrate_to(&base,"").unwrap();assert!(d.path.to_ascii_lowercase().contains("d:\\"));drop(m);
    let m=manager(&base);assert_eq!(m.info().path,d.path);assert_eq!(m.store().messages(&conv).unwrap().len(),1);assert_eq!(m.store().local_drafts(&doc,&revision).unwrap().len(),1);assert!(m.store().settings().unwrap().unwrap().thumbnail_open);assert_eq!(m.list_backups().unwrap()[0].id,backup.id);
    println!("actual D -> C -> D synthetic migration, C retained at {}, D locator reopens {}",c.path,d.path);
}
#[test]fn trusted_object_owner_never_authorizes_a_foreign_root_marker(){
    let base=lab();let m=manager(&base);let root=PathBuf::from(m.info().path);drop(m);
    let marker=root.join(".ainative-owner.json");let mut owner:serde_json::Value=serde_json::from_slice(&fs::read(&marker).unwrap()).unwrap();
    owner["sid"]=serde_json::json!("S-1-5-21-0-0-0-9999");let bytes=serde_json::to_vec(&owner).unwrap();fs::write(&marker,&bytes).unwrap();
    let error=super::directories::open_owned_root(&root).err().unwrap();assert!(matches!(error,DataError::Refused("foreign data directory")));assert_eq!(fs::read(&marker).unwrap(),bytes);
}
